#!/usr/bin/env python3
# Search V-invariant graphs on D = nonempty proper clopen subsets of the Cantor set
# (orbits of V on pairs = Venn emptiness patterns) that satisfy the Rado extension
# property for all families of size <= K. A pattern of (U, z) is the 4-bit vector
# (U&z, U-z, z-U, complement of U|z) nonempty. Per atom of the algebra generated by
# the family, z is Empty, Full or Mixed; splitting an atom realizes Mixed, and in the
# atomless algebra these three colours realize every pattern tuple.
import itertools, sys

K = int(sys.argv[1]) if len(sys.argv) > 1 else 3
MAXATOMS = int(sys.argv[2]) if len(sys.argv) > 2 else 2 ** K

def valid(p):
    a, b, c, d = p
    return (a or b) and (c or d) and (a or c) and (b or d) and (b or c)

P = [p for p in itertools.product((0, 1), repeat=4) if valid(p)]
swap = lambda p: (p[0], p[2], p[1], p[3])
orbits, seen = [], set()
for p in P:
    if p in seen:
        continue
    o = sorted({p, swap(p)})
    seen |= set(o)
    orbits.append(o)
orb_of = {p: i for i, o in enumerate(orbits) for p in o}
NO = len(orbits)
print("valid patterns", len(P), "symmetric orbits", NO, [o for o in orbits])

E, F, M = 0, 1, 2
S_BIT = {E: 0, F: 1, M: 1}  # z meets the atom
T_BIT = {E: 1, F: 0, M: 1}  # atom not contained in z

def configs(k):
    vecs = list(itertools.product((0, 1), repeat=k))
    for r in range(1, min(len(vecs), MAXATOMS) + 1):
        for Q in itertools.combinations(vecs, r):
            sets = [frozenset(j for j, v in enumerate(Q) if v[i]) for i in range(k)]
            if any(len(s) == 0 or len(s) == r for s in sets):
                continue
            if len(set(sets)) < k:
                continue
            yield Q, sets

def realized(Q, sets):
    r = len(Q)
    out = set()
    for col in itertools.product((E, F, M), repeat=r):
        if all(c == E for c in col) or all(c == F for c in col):
            continue  # z empty or everything
        if all(c != M for c in col):
            zs = frozenset(j for j in range(r) if col[j] == F)
            if zs in sets:
                continue  # z equals a family member
        tup = []
        for s in sets:
            a = any(S_BIT[col[j]] for j in s)
            b = any(T_BIT[col[j]] for j in s)
            c = any(S_BIT[col[j]] for j in range(r) if j not in s)
            d = any(T_BIT[col[j]] for j in range(r) if j not in s)
            tup.append(orb_of[(int(a), int(b), int(c), int(d))])
        out.add(tuple(tup))
    return out

allconf = [(Q, sets, realized(Q, sets)) for Q, sets in configs(K)]
print("K", K, "configurations", len(allconf))
survivors = []
for Smask in range(1, 2 ** NO - 1):
    ok = True
    for Q, sets, T in allconf:
        vecs = {tuple((Smask >> o) & 1 for o in t) for t in T}
        if len(vecs) < 2 ** K:
            ok = False
            break
    if ok:
        survivors.append(Smask)
print("surviving S masks", len(survivors))
for m in survivors:
    print("S", m, [orbits[i] for i in range(NO) if (m >> i) & 1])
